/* ============================================
   APP LAYOUT — full-page template
   Sidebar rail on the left, centered content area
   ============================================ */

.ds-app-layout {
  display: flex;
  min-height: 100vh;
  background-color: var(--color-bg-page-primary);
}

/* ============================================
   MAIN CONTENT AREA
   ============================================ */
.ds-app-layout__main {
  flex: 1;
  display: flex;
  justify-content: center;
  /* The rail's width plus, while it shows, the side panel's. */
  margin-left: calc(var(--ds-app-layout-rail, 64px) + var(--ds-app-layout-panel, 0px));
  padding: var(--padding-1000) var(--padding-500);
  transition: margin-left var(--motion-duration-slow) var(--motion-ease-emphasized);
  min-width: 0;
}

.ds-app-layout--expanded {
  --ds-app-layout-rail: 280px;
}

/* Panel mode's collapsed rail is the wider, labelled one. */
.ds-app-layout:not(.ds-app-layout--expanded):has(.ds-app-sidebar--panel-mode) {
  --ds-app-layout-rail: 80px;
}

.ds-app-layout:has(.ds-app-sidebar__panel--visible) {
  --ds-app-layout-panel: 240px;
}

/* ============================================
   CENTERED CONTENT WRAPPER
   ============================================ */
.ds-app-layout__content {
  width: 100%;
  max-width: 1120px;
  display: flex;
  flex-direction: column;
  gap: var(--gap-1000);
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 768px) {
  .ds-app-layout__main {
    margin-left: 0;
    padding: var(--padding-500) var(--padding-400);
  }

  .ds-app-layout--expanded .ds-app-layout__main {
    margin-left: 0;
  }
}

'use client';

import React, { useState, useCallback } from 'react';
import { AppSidebar } from '../AppSidebar/AppSidebar';
import type { AppSidebarSection, AppSidebarProfile } from '../AppSidebar/AppSidebar';
import './AppLayout.css';

export interface AppLayoutProps {
  /** Sidebar navigation sections */
  sections: AppSidebarSection[];
  /** Sidebar profile */
  profile?: AppSidebarProfile;
  /** Active nav item key */
  activeKey?: string;
  /** Active sub-item key */
  activeSubKey?: string;
  /** Active third-level item key, listed in the sidebar's side panel */
  activeTertiaryKey?: string;
  /** Where sub-items show: the sidebar's accordion, or straight into its side panel (see AppSidebar) */
  subNav?: 'accordion' | 'panel';
  /** Whether sidebar starts expanded */
  defaultExpanded?: boolean;
  /** Logo text next to icon */
  logoText?: string;
  /** Custom logo element */
  logo?: React.ReactNode;
  /** Page content — centred in the main area */
  children: React.ReactNode;
  /**
   * Colour scheme: 'dark' pins the layout to the dark theme (the historical
   * behaviour and the default); 'inherit' drops the pin so the layout
   * follows the surrounding data-theme like any other component.
   */
  theme?: 'dark' | 'inherit';
  /** Additional CSS classes on outer wrapper */
  className?: string;
}

/**
 * AppLayout — full-page template with a collapsible sidebar
 * and a centred content area.
 */
export const AppLayout = ({
  sections,
  profile,
  activeKey,
  activeSubKey,
  activeTertiaryKey,
  subNav,
  defaultExpanded = true,
  logoText,
  logo,
  children,
  theme = 'dark',
  className = '',
}: AppLayoutProps) => {
  const baseClass = 'ds-app-layout';
  const [expanded, setExpanded] = useState(defaultExpanded);

  const handleExpandedChange = useCallback((next: boolean) => {
    setExpanded(next);
  }, []);

  const classes = [
    baseClass,
    expanded ? `${baseClass}--expanded` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div className={classes} data-theme={theme === 'dark' ? 'dark' : undefined}>
      <AppSidebar
        sections={sections}
        profile={profile}
        activeKey={activeKey}
        activeSubKey={activeSubKey}
        activeTertiaryKey={activeTertiaryKey}
        subNav={subNav}
        expanded={expanded}
        onExpandedChange={handleExpandedChange}
        logoText={logoText}
        logo={logo}
      />
      <main className={`${baseClass}__main`}>
        <div className={`${baseClass}__content`}>
          {children}
        </div>
      </main>
    </div>
  );
};
